const tpl='NAME: {{name}}\nSUMMARY: {{summary}}\nSKILLS: {{skills}}';
const data={name:'Fiona Fiction',summary:'Entry-level technician (fictional).',skills:'soldering, wiring'};
let out=tpl;for(const k of Object.keys(data))out=out.replace('{{'+k+'}}',data[k]);
J({rendered:out.split('\n').length});assert(!out.includes('{{'),'rendered');

const FICTIONAL=['Fiona Fiction','Sam Sample','Pat Placeholder'];
const r={banner:'FICTIONAL EXAMPLE - not a real person',name:'Fiona Fiction',email:'fiona.fiction@example.invalid',sections:['summary','education','skills','projects']};
J({name:r.name,banner:!!r.banner});assert(FICTIONAL.includes(r.name),'fictional-name');assert(!!r.banner,'banner');

function guard(r){const okBanner=!!r.banner;const okEmail=String(r.email||'').endsWith('.invalid')||String(r.email||'').includes('example');return okBanner&&okEmail;}
const good={banner:1,email:'fiona.fiction@example.invalid'};const bad={name:'Real Person',email:'real@realmail.com'};
J({good:guard(good),bad:guard(bad)});assert(guard(good)&&!guard(bad),'guard');
